ition":{"x":450.0,"y":280.0},"send_product_images":false,"system_prompt":"You are a friendly customer-service assistant. Answer the customer''s question briefly using the provided context.","temperature":0.7,"type":"llm_reply","use_rag":true},{"id":"node_end_confirmed","label":"Handoff confirmed","position":{"x":850.0,"y":60.0},"type":"end"},{"id":"node_end_declined","label":"Handoff declined","position":{"x":850.0,"y":180.0},"type":"end"},{"id":"node_end_fallback","label":"End","position":{"x":650.0,"y":280.0},"type":"end"}],"variables":{},"version":"1.0"}'::jsonb),
  ('lead-capture-handoff', 'Lead capture + handoff', 'Tags high-intent inbounds as leads and hands off to the sales team in the messaging inbox.', 'lead-capture', '{"edges":[{"id":"edge_start_trigger","label":null,"source":"node_start","sourceHandle":"next","target":"node_trigger_lead","targetHandle":"prev"},{"id":"edge_match_tag","label":"high-intent","source":"node_trigger_lead","sourceHandle":"match","target":"node_tag_lead","targetHandle":"prev"},{"id":"edge_nomatch_reply","label":"general","source":"node_trigger_lead","sourceHandle":"no_match","target":"node_llm_reply","targetHandle":"prev"},{"id":"edge_tag_handoff","label":null,"source":"node_tag_lead","sourceHandle":"next","target":"node_handoff_sales","targetHandle":"prev"},{"id":"edge_handoff_confirmed","label":null,"source":"node_handoff_sales","sourceHandle":"confirmed","target":"node_end_confirmed","targetHandle":"prev"},{"id":"edge_handoff_declined","label":null,"source":"node_handoff_sales","sourceHandle":"declined","target":"node_end_declined","targetHandle":"prev"},{"id":"edge_reply_end","label":null,"source":"node_llm_reply","sourceHandle":"next","target":"node_end_reply","targetHandle":"prev"}],"nodes":[{"id":"node_start","label":"Start","position":{"x":50.0,"y":200.0},"type":"start"},{"confidence_threshold":0.7,"id":"node_trigger_lead","intents":["hard","handoff"],"keywords":[],"label":"Lead-like intent?","mode":"intent","position":{"x":250.0,"y":200.0},"type":"trigger"},{"id":"node_tag_lead","label":"Tag: lead_captured","position":{"x":450.0,"y":120.0},"tag_name":"lead_captured","tag_value":"true","type":"action_tag"},{"id":"node_handoff_sales","label":"Handoff to sales","position":{"x":650.0,"y":120.0},"private_note":"Lead captured. Tier hint: {{intent_tier}}.","team_id":"sales","type":"handoff"},{"id":"node_llm_reply","label":"Reply","max_tokens":800,"model_override":null,"position":{"x":450.0,"y":280.0},"send_product_images":false,"system_prompt":"You are a friendly assistant. Answer briefly using the provided context.","temperature":0.7,"type":"llm_reply","use_rag":true},{"id":"node_end_confirmed","label":"Handoff confirmed","position":{"x":850.0,"y":60.0},"type":"end"},{"id":"node_end_declined","label":"Handoff declined","position":{"x":850.0,"y":180.0},"type":"end"},{"id":"node_end_reply","label":"End","position":{"x":650.0,"y":280.0},"type":"end"}],"variables":{},"version":"1.0"}'::jsonb),
  ('stop-opt-out', 'STOP / opt-out (silent baseline)', 'Listens for STOP/unsubscribe keywords and tags the contact as opted_out. Attached silently to every tenant.', 'opt-out', '{"edges":[{"id":"edge_start_trigger","label":null,"source":"node_start","sourceHandle":"next","target":"node_trigger_stop","targetHandle":"prev"},{"id":"edge_match_tag","label":"STOP detected","source":"node_trigger_stop","sourceHandle":"match","target":"node_tag_opted_out","targetHandle":"prev"},{"id":"edge_nomatch_passthrough","label":"no opt-out","source":"node_trigger_stop","sourceHandle":"no_match","target":"node_end_passthrough","targetHandle":"prev"},{"id":"edge_tag_end","label":null,"source":"node_tag_opted_out","sourceHandle":"next","target":"node_end_opted_out","targetHandle":"prev"}],"nodes":[{"id":"node_start","label":"Start","position":{"x":50.0,"y":200.0},"type":"start"},{"confidence_threshold":0.7,"id":"node_trigger_stop","intents":[],"keywords":["stop","unsubscribe","henti","opt out","opt-out"],"label":"STOP keyword?","mode":"keyword","position":{"x":250.0,"y":200.0},"type":"trigger"},{"id":"node_tag_opted_out","label":"Tag: opted_out","position":{"x":450.0,"y":120.0},"tag_name":"opted_out","tag_value":"true","type":"action_tag"},{"id":"node_end_opted_out","label":"Opt-out recorded","position":{"x":650.0,"y":120.0},"type":"end"},{"id":"node_end_passthrough","label":"Pass-through","position":{"x":450.0,"y":280.0},"type":"end"}],"variables":{},"version":"1.0"}'::jsonb)
ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    category = EXCLUDED.category,
    definition = EXCLUDED.definition,
    last_updated_at = now();

-- Sanity check: confirm every expected slug is present after insert.
-- A row count != 4 means a template was added/removed without
-- updating the migration generator — investigate before merging.
DO $$
DECLARE
    expected_slugs TEXT[] := ARRAY['welcome-faq', 'booking', 'lead-capture-handoff', 'stop-opt-out'];
    actual_count INT;
BEGIN
    SELECT COUNT(*) INTO actual_count
    FROM flow_templates
    WHERE slug = ANY(expected_slugs);
    IF actual_count <> array_length(expected_slugs, 1) THEN
        RAISE EXCEPTION 'flow_templates seed mismatch: expected % rows, got %',
            array_length(expected_slugs, 1), actual_count;
    END IF;
END $$;

INSERT INTO schema_migrations (filename) VALUES ('038_flow_templates_seed.sql')
ON CONFLICT (filename) DO NOTHING;
